CREATE TABLE link_groups (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX group_owner ON link_groups(owner_id,position);
CREATE TABLE link_options (link_id TEXT PRIMARY KEY REFERENCES links(id), config TEXT NOT NULL DEFAULT '{}', password_hash TEXT NOT NULL DEFAULT '', access_version TEXT NOT NULL DEFAULT '', access_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE link_events (id TEXT PRIMARY KEY, link_id TEXT NOT NULL REFERENCES links(id), visitor TEXT NOT NULL, kind TEXT NOT NULL, channel TEXT NOT NULL DEFAULT '', device TEXT NOT NULL DEFAULT '', browser TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', value REAL NOT NULL DEFAULT 0, timestamp INTEGER NOT NULL, day TEXT NOT NULL);
CREATE INDEX event_link_day ON link_events(link_id,day,kind);
CREATE INDEX event_dedup ON link_events(link_id,visitor,kind,timestamp);
CREATE TABLE documents (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, name TEXT NOT NULL, draft TEXT NOT NULL DEFAULT '{}', published TEXT, version INTEGER NOT NULL DEFAULT 0, deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX documents_owner ON documents(owner_id,kind,deleted_at);
CREATE TABLE document_versions (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), version INTEGER NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(document_id,version));
CREATE TABLE leads (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), name TEXT NOT NULL, contact TEXT NOT NULL, message TEXT NOT NULL, created_at INTEGER NOT NULL, day TEXT NOT NULL);
CREATE INDEX leads_document ON leads(document_id,created_at);
CREATE TABLE qr_allocations (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), target_id TEXT NOT NULL, visitor TEXT NOT NULL, day TEXT NOT NULL, timestamp INTEGER NOT NULL, UNIQUE(document_id,visitor,day));
CREATE INDEX qr_target_day ON qr_allocations(document_id,target_id,day);
CREATE TABLE feature_limits (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE api_keys (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, secret_cipher TEXT NOT NULL, ips TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 1, quota INTEGER NOT NULL DEFAULT 1000, created_at INTEGER NOT NULL);
CREATE TABLE api_nonces (key_id TEXT NOT NULL REFERENCES api_keys(id), nonce TEXT NOT NULL, expires INTEGER NOT NULL, PRIMARY KEY(key_id,nonce));
CREATE INDEX nonce_expiry ON api_nonces(expires);
CREATE TABLE api_logs (id TEXT PRIMARY KEY, key_id TEXT NOT NULL REFERENCES api_keys(id), path TEXT NOT NULL, status INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX api_log_key ON api_logs(key_id,created_at);
CREATE TABLE notifications (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), message TEXT NOT NULL, read_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE link_health (link_id TEXT NOT NULL REFERENCES links(id), target TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'unknown', failures INTEGER NOT NULL DEFAULT 0, checked_at INTEGER, PRIMARY KEY(link_id,target));
CREATE TABLE partner_tokens (id TEXT PRIMARY KEY, link_id TEXT NOT NULL REFERENCES links(id), owner_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL, expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE feature_assets (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, body TEXT NOT NULL, deleted_at INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX asset_owner ON feature_assets(owner_id,created_at);
ALTER TABLE domains ADD COLUMN owner_id TEXT REFERENCES users(id);
CREATE TABLE domain_health (domain_id TEXT PRIMARY KEY REFERENCES domains(id), state TEXT NOT NULL, detail TEXT NOT NULL, checked_at INTEGER NOT NULL);
CREATE TABLE document_events (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), visitor TEXT NOT NULL, kind TEXT NOT NULL, timestamp INTEGER NOT NULL, day TEXT NOT NULL);
CREATE INDEX document_event_day ON document_events(document_id,day,kind);
ALTER TABLE links ADD COLUMN restore_enabled INTEGER;
CREATE INDEX feature_limit_expiry ON feature_limits(expires);
CREATE INDEX api_log_retention ON api_logs(created_at);
